<?php foreach ($product['variants'] as $variant): ?><form class="php-variant" method="post" action="<?= $u('cart') ?>"><h3><?= $e($variant['sku']) ?></h3><a class="text-button" href="<?= $u('calculator') ?>?variant_id=<?= $e($variant['id']) ?>">Calculate coverage ↗</a><p><?= $e($variant['finish']) ?> · <?= $m($variant['unit_price_minor']) ?> per <?= $e($variant['sell_unit']) ?></p>
<?php if ($variant['coverage_sqft_milli'] !== null): ?><p>Coverage: <?= $q($variant['coverage_sqft_milli']) ?> sqft per <?= $e($variant['sell_unit']) ?></p><?php endif; ?>
<input type="hidden" name="csrf" value="<?= $e($csrf) ?>"><input type="hidden" name="variant_id" value="<?= $e($variant['id']) ?>"><input type="hidden" name="cart_id" value="<?= $e($cart['id'] ?? '') ?>"><input type="hidden" name="cart_revision" value="<?= $e($cart['revision']) ?>">
<label>Quantity (<?= $e($variant['sell_unit']) ?>)<input name="quantity" type="number" min="<?= $q($variant['qty_increment_milli']) ?>" step="<?= $q($variant['qty_increment_milli']) ?>" value="<?= $q($variant['qty_increment_milli']) ?>" required></label><small>Sold in increments of <?= $q($variant['qty_increment_milli']) ?> <?= $e($variant['sell_unit']) ?>. Adding replaces this variant's cart quantity.</small>
